-- Opt-in connected check: execute as migration owner. Never run at startup.
-- Fixtures, capability tokens and rate-limit/idempotency records all roll back.
BEGIN;
CREATE TEMP TABLE page_checks(name text PRIMARY KEY, result text);
DO $tests$
DECLARE
 o uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); l uuid:=gen_random_uuid(); p uuid:=gen_random_uuid();
 b2 uuid:=gen_random_uuid(); l2 uuid:=gen_random_uuid(); p2 uuid:=gen_random_uuid();
 u uuid:=gen_random_uuid(); u2 uuid:=gen_random_uuid(); m uuid:=gen_random_uuid(); st uuid:=gen_random_uuid(); inactive uuid:=gen_random_uuid();
 sp uuid:=gen_random_uuid(); s1 uuid:=gen_random_uuid(); s2 uuid:=gen_random_uuid(); foreign_service uuid:=gen_random_uuid(); unassigned uuid:=gen_random_uuid();
 d date:=(now() AT TIME ZONE 'America/New_York')::date+7;
 t timestamptz; r jsonb; live jsonb; slots jsonb; hold jsonb; v bigint:=1; n bigint; who uuid; sig regprocedure;
 slug text:='page-check-'||p::text;
BEGIN
 INSERT INTO auth.users(id,email,email_confirmed_at) SELECT x,'page-check-'||x::text||'@example.test',now() FROM unnest(ARRAY[u,u2,m,st,inactive]) x;
 INSERT INTO public.organizations(id,name,slug) VALUES(o,'Page draft rollback','page-check-'||o::text);
 INSERT INTO public.businesses(id,organization_id,name,slug,status) VALUES(b,o,'Page draft rollback','page-check-'||b::text,'active'),(b2,o,'Page draft rollback','page-check-'||b2::text,'active');
 INSERT INTO public.locations(id,business_id,name,slug,timezone) VALUES(l,b,'Test','test','America/New_York'),(l2,b2,'Other','other','America/New_York');
 INSERT INTO public.business_members(business_id,user_id,role,active,all_locations,can_manage_customers,can_manage_services) VALUES(b,u,'owner',true,true,true,true),(b2,u2,'owner',true,true,true,true),(b,m,'manager',true,true,true,true),(b,st,'staff',true,false,false,false),(b,inactive,'owner',false,true,true,true);
 INSERT INTO public.business_settings(business_id,minimum_notice_minutes,reschedule_notice_minutes) VALUES(b,0,0),(b2,0,0);
 INSERT INTO public.booking_pages(id,business_id,location_id,slug,title,description,status,published_at) VALUES(p,b,l,slug,'Original','Original description','published',now()),(p2,b2,l2,'page-check-'||p2::text,'Other','Other','published',now());
 INSERT INTO public.staff_profiles(id,business_id,display_name) VALUES(sp,b,'Staff');
 INSERT INTO public.staff_locations(business_id,staff_id,location_id) VALUES(b,sp,l);
 INSERT INTO public.services(id,business_id,name,duration_minutes) VALUES(s1,b,'Visible',30),(s2,b,'Hidden',30),(unassigned,b,'Unassigned',30),(foreign_service,b2,'Other tenant',30);
 INSERT INTO public.service_locations(business_id,service_id,location_id) VALUES(b,s1,l),(b,s2,l),(b2,foreign_service,l2);
 INSERT INTO public.staff_services(business_id,staff_id,service_id) VALUES(b,sp,s1),(b,sp,s2),(b,sp,unassigned);
 INSERT INTO public.business_hours(business_id,location_id,iso_weekday,opens_at,closes_at) VALUES(b,l,extract(isodow FROM d)::smallint,'09:00','17:00');
 INSERT INTO public.staff_availability(business_id,location_id,staff_id,iso_weekday,opens_at,closes_at,effective_from) VALUES(b,l,sp,extract(isodow FROM d)::smallint,'09:00','17:00',d-1);
 t:=(d+time '09:00') AT TIME ZONE 'America/New_York';
 PERFORM set_config('role','service_role',true);
 live:=public.get_public_booking_page(slug);
 r:=public.get_booking_page_draft(b,u);
 IF jsonb_array_length(live->'services')<>2 OR r->>'title'<>'Original' OR (r->>'row_version')::bigint<>1 OR NOT (r->>'published')::boolean OR jsonb_array_length(r->'service_ids')<>2 THEN RAISE EXCEPTION 'legacy fallback mismatch'; END IF;
 EXECUTE 'RESET ROLE';
 IF EXISTS(SELECT 1 FROM private.booking_page_drafts WHERE page_id=p) THEN RAISE EXCEPTION 'read created a draft'; END IF;
 INSERT INTO page_checks VALUES('01 legacy published page preserved; draft preview is read-only','PASS');
 PERFORM set_config('role','service_role',true);
 r:=public.save_booking_page_draft(b,u,v,'Draft title','Draft description',false,ARRAY[s1,s1]); v:=(r->>'row_version')::bigint;
 IF v<>2 OR jsonb_array_length(r->'service_ids')<>1 OR public.get_public_booking_page(slug)<>live THEN RAISE EXCEPTION 'draft leaked or duplicates not normalized'; END IF;
 BEGIN PERFORM public.save_booking_page_draft(b,u,1,'Stale','',true,ARRAY[s1]); RAISE EXCEPTION 'stale save allowed'; EXCEPTION WHEN SQLSTATE 'P0409' THEN NULL; END;
 BEGIN PERFORM public.set_booking_page_publication(b,u,NULL,true); RAISE EXCEPTION 'null version allowed'; EXCEPTION WHEN SQLSTATE 'P0409' THEN NULL; END;
 FOR who IN SELECT unnest(ARRAY[m,st,inactive,u2,NULL::uuid]) LOOP
  BEGIN PERFORM public.get_booking_page_draft(b,who); RAISE EXCEPTION 'nonowner preview allowed'; EXCEPTION WHEN SQLSTATE 'P0403' THEN NULL; END;
  BEGIN PERFORM public.save_booking_page_draft(b,who,v,'Denied','',true,ARRAY[s1]); RAISE EXCEPTION 'nonowner save allowed'; EXCEPTION WHEN SQLSTATE 'P0403' THEN NULL; END;
  BEGIN PERFORM public.set_booking_page_publication(b,who,v,true); RAISE EXCEPTION 'nonowner publish allowed'; EXCEPTION WHEN SQLSTATE 'P0403' THEN NULL; END;
 END LOOP;
 BEGIN PERFORM public.save_booking_page_draft(b,u,v,'Invalid','',true,ARRAY[foreign_service]); RAISE EXCEPTION 'cross-tenant service allowed'; EXCEPTION WHEN SQLSTATE 'P0422' THEN NULL; END;
 BEGIN PERFORM public.save_booking_page_draft(b,u,v,'Invalid','',true,ARRAY[unassigned]); RAISE EXCEPTION 'unassigned service allowed'; EXCEPTION WHEN SQLSTATE 'P0422' THEN NULL; END;
 BEGIN PERFORM public.save_booking_page_draft(b,u,v,'Invalid','',NULL,ARRAY[s1]); RAISE EXCEPTION 'null toggle allowed'; EXCEPTION WHEN SQLSTATE 'P0422' THEN NULL; END;
 BEGIN PERFORM public.save_booking_page_draft(b,u,v,'Invalid','',true,NULL); RAISE EXCEPTION 'null services allowed'; EXCEPTION WHEN SQLSTATE 'P0422' THEN NULL; END;
 EXECUTE 'RESET ROLE';
 INSERT INTO page_checks VALUES('02 save isolated, version 1 to 2, duplicate services normalized','PASS'),('03 stale/null version P0409','PASS'),('04 manager/staff/inactive/cross-owner/null actor P0403 for all owner RPCs','PASS'),('05 cross-tenant/unassigned services and null input P0422','PASS');
 PERFORM set_config('role','service_role',true);
 r:=public.set_booking_page_publication(b,u,v,true); v:=(r->>'row_version')::bigint;
 live:=public.get_public_booking_page(slug);
 IF v<>3 OR live->>'title'<>'Draft title' OR live->>'description'<>'Draft description' OR (live->>'staff_selection_enabled')::boolean OR jsonb_array_length(live->'services')<>1 OR r->>'slug'<>slug OR r->'live_service_ids'<>r->'service_ids' THEN RAISE EXCEPTION 'publish mismatch'; END IF;
 slots:=public.get_availability(p,s1,d,d,gen_random_uuid(),'[]',1);
 IF jsonb_array_length(slots)=0 THEN RAISE EXCEPTION 'disabled picker still filtered staff preference'; END IF;
 BEGIN PERFORM public.get_availability(p,s2,d,d,NULL,'[]',1); RAISE EXCEPTION 'hidden availability allowed'; EXCEPTION WHEN SQLSTATE 'P0404' THEN NULL; END;
 EXECUTE 'RESET ROLE';
 SELECT count(*) INTO n FROM public.appointment_holds WHERE business_id=b;
 PERFORM set_config('role','service_role',true);
 BEGIN PERFORM public.create_booking_hold('page-check-'||p::text,p,s2,sp,NULL,t,'[]',1,gen_random_uuid()); RAISE EXCEPTION 'hidden hold allowed'; EXCEPTION WHEN SQLSTATE 'P0409' THEN NULL; END;
 hold:=public.create_booking_hold('page-check-'||p::text,p,s1,sp,NULL,t,'[]',1,gen_random_uuid());
 PERFORM public.confirm_booking('page-check-'||p::text,hold->>'hold_token',NULL,NULL,jsonb_build_object('full_name','Guest','email','guest@example.test'),'','[]',gen_random_uuid());
 EXECUTE 'RESET ROLE';
 IF (SELECT count(*) FROM public.appointment_holds WHERE business_id=b)<>n+1 THEN RAISE EXCEPTION 'denied hold created data'; END IF;
 INSERT INTO page_checks VALUES('06 publish version 2 to 3, title/description/toggle/visible services applied, slug retained','PASS'),('07 disabled staff preference ignored; hidden availability P0404 and hold P0409','PASS'),('08 existing public visible hold and guest confirmation succeed','PASS');
 PERFORM set_config('role','service_role',true);
 r:=public.save_booking_page_draft(b,u,v,'Next draft','Next description',true,ARRAY[s2]); v:=(r->>'row_version')::bigint;
 IF public.get_public_booking_page(slug)<>live THEN RAISE EXCEPTION 'second draft leaked'; END IF;
 r:=public.set_booking_page_publication(b,u,v,false); v:=(r->>'row_version')::bigint;
 BEGIN PERFORM public.get_public_booking_page(slug); RAISE EXCEPTION 'unpublished projection allowed'; EXCEPTION WHEN SQLSTATE 'P0404' THEN NULL; END;
 BEGIN PERFORM public.get_availability(p,s1,d,d,NULL,'[]',1); RAISE EXCEPTION 'unpublished availability allowed'; EXCEPTION WHEN SQLSTATE 'P0404' THEN NULL; END;
 BEGIN PERFORM public.create_booking_hold('page-check-'||p::text,p,s1,sp,NULL,t+interval '2 hours','[]',1,gen_random_uuid()); RAISE EXCEPTION 'unpublished hold allowed'; EXCEPTION WHEN SQLSTATE 'P0404' THEN NULL; END;
 slots:=public.get_dashboard_booking_availability(p,s2,d,d,sp,'[]',1,u);
 IF jsonb_array_length(slots)=0 THEN RAISE EXCEPTION 'authorized dashboard hidden/unpublished availability blocked'; END IF;
 hold:=public.create_dashboard_booking_hold('page-check-dashboard-'||p::text,p,s2,sp,NULL,t+interval '2 hours','[]',1,gen_random_uuid(),u);
 BEGIN PERFORM public.create_dashboard_booking_hold('page-check-dashboard-'||p::text,p,s2,sp,NULL,t+interval '3 hours','[]',1,gen_random_uuid(),u2); RAISE EXCEPTION 'cross-tenant dashboard allowed'; EXCEPTION WHEN SQLSTATE 'P0403' THEN NULL; END;
 BEGIN PERFORM public.get_dashboard_booking_availability(p,s2,d,d,sp,'[]',1,st); RAISE EXCEPTION 'staff dashboard allowed'; EXCEPTION WHEN SQLSTATE 'P0403' THEN NULL; END;
 BEGIN PERFORM public.get_dashboard_booking_availability(p,s2,d,d,sp,'[]',1,NULL); RAISE EXCEPTION 'actorless dashboard allowed'; EXCEPTION WHEN SQLSTATE 'P0403' THEN NULL; END;
 IF jsonb_array_length(public.get_dashboard_booking_availability(p,s2,d,d,sp,'[]',1,m))=0 THEN RAISE EXCEPTION 'CRM manager blocked'; END IF;
 BEGIN PERFORM public.get_dashboard_booking_availability(p,unassigned,d,d,sp,'[]',1,u); RAISE EXCEPTION 'dashboard location bypass'; EXCEPTION WHEN SQLSTATE 'P0404' THEN NULL; END;
 EXECUTE 'RESET ROLE';
 INSERT INTO page_checks VALUES('09 second draft isolated, unpublish suppresses all public paths','PASS'),('10 owner dashboard hidden/unpublished availability and hold succeed; CRM manager allowed','PASS'),('11 dashboard cross-tenant/staff/null actor P0403; unassigned service P0404','PASS');
 PERFORM set_config('role','service_role',true);
 r:=public.set_booking_page_publication(b,u,v,true); v:=(r->>'row_version')::bigint;
 live:=public.get_public_booking_page(slug);
 IF live->>'title'<>'Next draft' OR NOT (live->>'staff_selection_enabled')::boolean OR (live->'services'->0->>'service_id')::uuid<>s2 THEN RAISE EXCEPTION 'republish did not use saved draft'; END IF;
 IF public.get_availability(p,s2,d,d,gen_random_uuid(),'[]',1)<>'[]'::jsonb THEN RAISE EXCEPTION 'enabled staff preference ignored'; END IF;
 r:=public.save_booking_page_draft(b,u,v,'Empty','',true,ARRAY[]::uuid[]); v:=(r->>'row_version')::bigint;
 r:=public.set_booking_page_publication(b,u,v,true); v:=(r->>'row_version')::bigint;
 IF public.get_public_booking_page(slug)->'services'<>'[]'::jsonb THEN RAISE EXCEPTION 'empty selection reverted to all services'; END IF;
 BEGIN PERFORM public.get_availability(p,s2,d,d,NULL,'[]',1); RAISE EXCEPTION 'empty selection availability allowed'; EXCEPTION WHEN SQLSTATE 'P0404' THEN NULL; END;
 r:=public.save_booking_page_draft(b,u,v,'Inactive draft','',true,ARRAY[s1]); v:=(r->>'row_version')::bigint;
 EXECUTE 'RESET ROLE';
 UPDATE public.service_locations SET active=false WHERE business_id=b AND service_id=s1;
 PERFORM set_config('role','service_role',true);
 BEGIN PERFORM public.set_booking_page_publication(b,u,v,true); RAISE EXCEPTION 'invalidated draft published'; EXCEPTION WHEN SQLSTATE 'P0422' THEN NULL; END;
 EXECUTE 'RESET ROLE';
 IF (SELECT row_version FROM public.booking_pages WHERE id=p)<>v THEN RAISE EXCEPTION 'failed publish changed version'; END IF;
 BEGIN INSERT INTO private.booking_page_draft_services(business_id,page_id,location_id,service_id) VALUES(b,p,l,foreign_service); RAISE EXCEPTION 'tenant FK allowed foreign service'; EXCEPTION WHEN foreign_key_violation THEN NULL; END;
 IF (SELECT count(*) FROM private.audit_logs WHERE business_id=b AND action LIKE 'booking_page.%')<>8 THEN RAISE EXCEPTION 'audit count mismatch'; END IF;
 INSERT INTO page_checks VALUES('12 republish saved draft; enabled staff preference honored','PASS'),('13 empty selection stays empty across projection/availability','PASS'),('14 publication revalidates assignments, P0422 and version unchanged','PASS'),('15 tenant FK 23503; eight successful edit/publication audit rows','PASS');
 FOR sig IN SELECT proc.oid::regprocedure FROM pg_proc proc JOIN pg_namespace ns ON ns.oid=proc.pronamespace WHERE ns.nspname='public' AND proc.proname IN ('get_booking_page_draft','save_booking_page_draft','set_booking_page_publication','get_dashboard_booking_availability','create_dashboard_booking_hold') LOOP
  IF has_function_privilege('anon',sig,'EXECUTE') OR has_function_privilege('authenticated',sig,'EXECUTE') OR NOT has_function_privilege('service_role',sig,'EXECUTE') THEN RAISE EXCEPTION 'bad grants on %',sig; END IF;
 END LOOP;
 PERFORM set_config('role','anon',true);
 BEGIN PERFORM public.get_booking_page_draft(b,u); RAISE EXCEPTION 'anon draft call allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 EXECUTE 'RESET ROLE';
 PERFORM set_config('role','authenticated',true);
 BEGIN PERFORM public.get_booking_page_draft(b,u); RAISE EXCEPTION 'authenticated draft call allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 EXECUTE 'RESET ROLE';
 INSERT INTO page_checks VALUES('16 all new public RPC grants server-only; direct anon/authenticated P0409-independent 42501','PASS');
END;
$tests$;
SELECT * FROM page_checks ORDER BY name;
ROLLBACK;